import 'package:flutter/material.dart';

/// Shows a numbered-grid picker dialog (used for chapter and verse
/// selection) and returns once the user picks an item or cancels.
///
/// [itemCount] cells are generated by index; [labelForIndex] supplies each
/// cell's display text (defaults to `index + 1`, used for chapters), and
/// [isSelectedIndex]/[onSelectedIndex] operate on the 0-based index so
/// callers can select by index even when the display label isn't
/// contiguous (e.g. verse numbers).
Future<void> showGridSelectorDialog(
  BuildContext context, {
  required String title,
  required int itemCount,
  required bool Function(int index) isSelectedIndex,
  required ValueChanged<int> onSelectedIndex,
  String Function(int index)? labelForIndex,
}) {
  return showDialog<void>(
    context: context,
    builder: (dialogContext) {
      return AlertDialog(
        title: Text(title),
        content: SizedBox(
          width: double.maxFinite,
          child: GridView.builder(
            shrinkWrap: true,
            gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(
              maxCrossAxisExtent: 72,
              crossAxisSpacing: 8,
              mainAxisSpacing: 8,
              childAspectRatio: 1.4,
            ),
            itemCount: itemCount,
            itemBuilder: (context, index) {
              final selected = isSelectedIndex(index);
              final label = labelForIndex?.call(index) ?? '${index + 1}';
              final colorScheme = Theme.of(context).colorScheme;
              // Each cell gets its own Material so the ripple is painted
              // inside the scrolling grid. An `Ink` decoration would paint
              // on the dialog's Material and bleed past the scroll clip.
              return Material(
                color: selected
                    ? colorScheme.primaryContainer
                    : colorScheme.surfaceContainerHighest,
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(8),
                  side: selected
                      ? BorderSide(color: colorScheme.primary, width: 2)
                      : BorderSide.none,
                ),
                clipBehavior: Clip.antiAlias,
                child: InkWell(
                  onTap: () {
                    Navigator.pop(dialogContext);
                    onSelectedIndex(index);
                  },
                  child: Center(
                    child: Text(
                      label,
                      style: TextStyle(
                        fontWeight: selected
                            ? FontWeight.bold
                            : FontWeight.normal,
                        color: selected ? colorScheme.onPrimaryContainer : null,
                      ),
                    ),
                  ),
                ),
              );
            },
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('Cancel'),
          ),
        ],
      );
    },
  );
}
